package jp.reader.manga;
import android.content.Context;import java.io.*;import java.util.concurrent.*;import java.util.*;
class Test{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);}public static void main(String[] x)throws Exception{File dir=java.nio.file.Files.createTempDirectory("manga-cache-test").toFile();dir.mkdirs();Context ctx=new Context(dir);String url="https://example.com/a.zip";byte[] bytes=new byte[20000];new Random(3).nextBytes(bytes);CountDownLatch l=new CountDownLatch(1);DownloadCache.start(ctx,new Dav(bytes),url,msg->{System.out.println(msg);l.countDown();});ok(l.await(5,TimeUnit.SECONDS),"background completion");File f=DownloadCache.available(ctx,url);ok(f!=null&&Arrays.equals(bytes,java.nio.file.Files.readAllBytes(f.toPath())),"download persisted identical");f.setLastModified(System.currentTimeMillis()-31L*24*60*60*1000);ok(DownloadCache.available(ctx,url)==null&&!f.exists(),"expiry after 30 days");CountDownLatch l2=new CountDownLatch(1);DownloadCache.start(ctx,new Dav(bytes),url,msg->l2.countDown());ok(l2.await(5,TimeUnit.SECONDS),"second download");ok(DownloadCache.delete(ctx,url),"saved file deletion reports success");ok(DownloadCache.available(ctx,url)==null,"delete on completion");ok(DownloadCache.delete(ctx,url),"missing cache deletion succeeds");System.exit(0);}}
